parameters.text:
=You are triaging incoming media operations requests for a streaming content team.
Classify this request into exactly one request_type and one urgency level.

request_type:
- new_delivery: a title or asset not yet delivered, needing encode and delivery
- redelivery_fix: an asset already delivered that is wrong or broken and must be replaced
- metadata_correction: title, synopsis, artwork, or ratings are wrong; the video itself is fine
- caption_subtitle: captions, subtitles, or SDH are missing, mistimed, or incorrect
- qc_escalation: a quality problem needing a judgment call, not a straightforward fix

urgency:
- urgent: the title is already live and viewers are seeing something wrong or broken, or a stated deadline falls within 24 hours of today
- standard: a stated deadline between 24 and 72 hours from today
- low: a stated deadline more than 72 hours away, or no deadline at all -- cleanup, housekeeping, or a cosmetic issue on a title that is otherwise playing correctly

If a request contains more than one problem, classify the one that blocks delivery.

Today's date: {{ $json.reference_date }}

Requester: {{ $json.name }}
Title / Asset ID: {{ $json.asset_id }}
Platform: {{ $json.platform }}
Already live: {{ $json.is_live }}
Needed by: {{ $json.needed_by }}
Request: {{ $json.details }}

summary: one line, maximum 20 words.
reasoning: one sentence naming the signal that decided the type and the urgency.

parameters.jsCode:
const outputs = $input.all();
const upstream = $('Normalize Request').all();

function sourceFor(i) {
  try {
    return $('Normalize Request').itemMatching(i).json;
  } catch (e) {
    return upstream[i] ? upstream[i].json : {};
  }
}

const rows = [];
let typeOk = 0, urgencyOk = 0, bothOk = 0;
let scored = 0, unlabeled = 0, live = 0;

for (let i = 0; i < outputs.length; i++) {
  const got = outputs[i].json.output || {};
  const src = sourceFor(i);

  const expType = (src.expected_type || '').trim();
  const expUrg = (src.expected_urgency || '').trim();

  const row = {
    id: src.id || (i + 1),
    details: (src.details || '').slice(0, 70),
    got_type: got.request_type,
    got_urgency: got.urgency,
    expected_type: expType,
    expected_urgency: expUrg,
    reasoning: got.reasoning,
  };

  // Three states, not two. A live form submission has no labels at all. A test
  // item with blank or TODO_MARIO labels is homework, not data. Scoring
  // against a placeholder would invent a wrong answer and quietly deflate the
  // number.
  const isTestItem = typeof src.id === 'number';
  const ready = expType && expUrg
    && expType !== 'TODO_MARIO' && expUrg !== 'TODO_MARIO';

  if (!ready) {
    if (isTestItem) {
      row.verdict = 'NEEDS LABEL';
      unlabeled++;
    } else {
      row.verdict = 'live submission';
      live++;
    }
    rows.push(row);
    continue;
  }

  const tOk = got.request_type === expType;
  const uOk = got.urgency === expUrg;
  if (tOk) typeOk++;
  if (uOk) urgencyOk++;
  if (tOk && uOk) bothOk++;
  scored++;

  row.verdict = tOk && uOk ? 'exact' : (tOk ? 'urgency miss' : (uOk ? 'type miss' : 'both miss'));
  rows.push(row);
}

const pct = (n) => scored ? Math.round((n / scored) * 1000) / 10 : 0;

// Reported against the number actually scored, never against 15. A denominator
// that includes items you never scored is a test set flattering itself.
const scorecard = {
  items_scored: scored,
  items_needing_labels: unlabeled,
  live_submissions: live,
  type_accuracy: `${typeOk}/${scored} (${pct(typeOk)}%)`,
  urgency_accuracy: `${urgencyOk}/${scored} (${pct(urgencyOk)}%)`,
  exact_match: `${bothOk}/${scored} (${pct(bothOk)}%)`,
};

if (unlabeled > 0) {
  scorecard.WARNING = `${unlabeled} test items have no label yet. The accuracy above is computed on ${scored} items only.`;
}

// Match verdicts exactly. The first version of this line used
// verdict.includes('miss') and quietly reported every live form submission as
// a miss, because the word "submission" contains "miss". Substring matching on
// a value that is really an enum is a bug waiting for the right input.
const MISS_VERDICTS = new Set(['type miss', 'urgency miss', 'both miss']);
const misses = rows.filter(r => MISS_VERDICTS.has(r.verdict));

return [{ json: { scorecard, misses, rows } }];

